public class MaximumSubarray {

    // === 方法 1: Kadane（滚动变量），只求最大和 ===
    public int maxSubArray(int[] nums) {
        int cur = nums[0];
        int best = nums[0];
        for (int i = 1; i < nums.length; i++) {
            cur = Math.max(nums[i], cur + nums[i]); // 延续 or 重启
            best = Math.max(best, cur);
        }
        return best;
    }

    // === 方法 2: Kadane + 返回起止下标 ===
    public int[] maxSubArrayWithRange(int[] nums) {
        int cur = nums[0], best = nums[0];
        int candStart = 0, bestStart = 0, bestEnd = 0;
        for (int i = 1; i < nums.length; i++) {
            if (cur + nums[i] < nums[i]) {
                cur = nums[i];
                candStart = i;          // 重启，记录候选起点
            } else {
                cur = cur + nums[i];    // 延续
            }
            if (cur > best) {
                best = cur;
                bestStart = candStart;  // 锁定区间
                bestEnd = i;
            }
        }
        return new int[]{best, bestStart, bestEnd};
    }

    // === 方法 3: 分治 ===
    public int maxSubArrayDivide(int[] nums) {
        return divide(nums, 0, nums.length - 1);
    }

    private int divide(int[] nums, int lo, int hi) {
        if (lo == hi) return nums[lo];
        int mid = lo + (hi - lo) / 2;
        int leftMax  = divide(nums, lo, mid);
        int rightMax = divide(nums, mid + 1, hi);

        // 跨中点：从中点向左扩 + 从中点+1 向右扩
        int leftSum = Integer.MIN_VALUE, sum = 0;
        for (int i = mid; i >= lo; i--) {
            sum += nums[i];
            leftSum = Math.max(leftSum, sum);
        }
        int rightSum = Integer.MIN_VALUE;
        sum = 0;
        for (int i = mid + 1; i <= hi; i++) {
            sum += nums[i];
            rightSum = Math.max(rightSum, sum);
        }
        int crossMax = leftSum + rightSum;

        return Math.max(Math.max(leftMax, rightMax), crossMax);
    }

    public static void main(String[] args) {
        MaximumSubarray s = new MaximumSubarray();
        int[] nums = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
        System.out.println(s.maxSubArray(nums));              // 6
        int[] range = s.maxSubArrayWithRange(nums);
        System.out.println("max=" + range[0] + " range=[" + range[1] + "," + range[2] + "]"); // max=6 range=[3,6]
        System.out.println(s.maxSubArrayDivide(nums));        // 6

        // 全负数组
        int[] neg = {-3, -2, -1};
        System.out.println(s.maxSubArray(neg));               // -1
    }
}
